  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://jamieanne.co/pages/ambassadors', 'official_site', 'affiliate', 'Jamie Anne''s own ambassadors page (''The Healthy Skin Club'', run via Roster) publishes the pay structure: 20% commission on Jamie Anne products and 10% on everything else from day one, rising to 30% on Jamie Anne products at the Inner Circle tier; followers get 10% off their first order. There is no follower-count gate (US-based, 18+), commissions are tracked and paid monthly via Roster, ambassadors receive free product through content campaigns, and higher tiers carry product credits of $200+. The page calls the program brand new and recruiting founding ambassadors, but publishes no absolute creator counts, so saturation is recorded as unknown; no earnings-cap statement is published, so the cap is recorded as unknown.', 'verified', now());
