  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Dippin'' Daisy''s Affiliate Program (ShareASale) — 10% per sale', 'https://linkclicky.com/affiliate-program/dippin-daisys/', 'https://linkclicky.com/affiliate-program/dippin-daisys/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/dippin-daisys/', 'listing', 'affiliate', 'LinkClicky''s ShareASale program listing for Dippin'' Daisy''s states the program runs on ShareASale, pays 10% per sale with a 30-day cookie, and is open in all regions. The brand also runs a separate ambassador route via a Google form at a lower 5% code-based rate; the ShareASale program is the stronger, featured route. No fetched page states an earnings cap, so commission_cap is unknown, and no absolute creator-count evidence was found, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.dippindaisys.com', 'official_site', 'general', 'The brand''s own homepage presents a women-owned swimwear label selling bikinis, one-pieces and sets made from recycled fabrics, claiming over 8,500 five-star reviews.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 12, 8, 9, 4, '{"compensation": "10% per sale on ShareASale with a 30-day cookie is mid-range for swimwear; no earnings cap is stated, so the cap is honestly unknown.", "contact_access": "Application runs through the ShareASale listing; no direct program email is published on the fetched pages.", "credibility": "Established DTC swim label with a substantial claimed review base (8,500+ five-star reviews on its homepage).", "niche_fit": "Swimwear is highly visual and seasonal-fashion friendly, a natural fit for short-form try-on and beach content.", "opportunity_availability": "Open network application on ShareASale, available in all regions per the listing.", "ugc_evidence": "An active ShareASale program plus a separate ambassador application route show the brand works with promoters, though no paid-content campaign terms are published."}'::jsonb);
