  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://blackboughswim.com', 'official_site', 'general', 'The brand''s own homepage sells bikinis, one-pieces, beachwear and accessories and invites customers to tag @blackboughswim on Instagram to be featured; the verified Instagram profile has about 989K followers. Philippine press coverage (Zalora Philippines / Lazada Brand Wiki) records the brand was founded in Manila in 2017 by Jemina Ty.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 14, 8, 9, 4, '{"compensation": "12% per sale is above average for swimwear; the 15-day cookie is short, and no earnings cap is stated, so the cap is honestly unknown.", "contact_access": "Application runs through the ShareASale listing; no direct program email is published on the fetched pages.", "credibility": "Founded 2017 in Manila, grown into an eight-figure global DTC label per Philippine press coverage, with a verified ~989K-follower Instagram.", "niche_fit": "Tropical swimwear with strong Gen-Z social traction is a natural fit for swim and vacation content.", "opportunity_availability": "Open network application on ShareASale, available in all regions per the listing.", "ugc_evidence": "The brand actively features customer and creator posts (''tag us to be featured'') and runs an open ShareASale program, though no paid-brief terms are published."}'::jsonb);
