  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ten Thousand Affiliate Program (Impact) — 1-2% per sale', 'https://linkclicky.com/affiliate-program/ten-thousand/', 'https://linkclicky.com/affiliate-program/ten-thousand/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/ten-thousand/', 'listing', 'affiliate', 'LinkClicky''s program listing for Ten Thousand states the program runs on Impact and pays 1%-2% per sale; Lasso''s program page reports 1.6% per sale with a 30-day cookie, which sits inside that range, and a network EPC listing reports about 1%. Because the sources publish a range rather than one rate, commission_rate is recorded as null with the 1-2% range documented here; a Shopper.com listing claiming 5-10% is generic boilerplate that conflicts with the network-profile reporting and is not used. No fetched page states an earnings cap, so commission_cap is unknown, and no absolute creator-count evidence was found, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 9, 4, 8, 8, 4, '{"compensation": "Only 1-2% per sale (Lasso reports 1.6%) \u2014 the lowest rate in this group \u2014 and no earnings cap is stated, so the cap is honestly unknown.", "contact_access": "Application runs through the Impact listing; no direct program email is published on the fetched pages.", "credibility": "Established US performance-apparel brand founded in 2014 with national recognition in the training niche.", "niche_fit": "Men''s training apparel fits fitness-fashion content, though the audience is narrower than general fashion.", "opportunity_availability": "Open network application on Impact.", "ugc_evidence": "An open Impact program is the main creator evidence; no published creator briefs or campaign terms were found on the fetched pages."}'::jsonb);
