  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Own program (Buzzbassador)', 15, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.toms.com/pages/toms-besties-program-terms-conditions.', 'https://www.toms.com/pages/toms-besties-program-terms-conditions', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'TOMS Besties Program (Buzzbassador) — Creator Tier 15% of net sales', 'https://www.toms.com/pages/toms-besties-program-terms-conditions', 'https://www.toms.com/pages/toms-besties-program-terms-conditions', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.toms.com/pages/toms-besties-program-terms-conditions', 'official_site', 'affiliate', 'TOMS'' own Besties Program Terms & Conditions (fetched in full from toms.com) set out three tiers paid on net sales (after discounts, taxes and shipping): Creator Tier 15%, Fan Tier 10%, Customer Tier 10%. The program runs through Buzzbassador, pays monthly via Tremendous in cash or, at TOMS'' discretion, store credit (not store-credit-only, so it passes the exclusion), and names besties@toms.com as the program contact. The Creator Tier rate of 15 is recorded with the lower tiers documented here. The terms state no earnings cap, so commission_cap is unknown, and no absolute member-count evidence was found, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 18, 16, 14, 9, 5, '{"compensation": "Creator Tier pays 15% of net sales \u2014 the strongest verified fashion rate in this group; Fan and Customer tiers pay 10%. No earnings cap is stated, so the cap is honestly unknown.", "contact_access": "A published program email (besties@toms.com) plus full terms on the brand''s own domain is the best contact access in this group.", "credibility": "A globally recognized footwear brand founded in 2006 with a long-standing giving model.", "niche_fit": "Everyday footwear with a strong impact story fits fashion, lifestyle and cause-driven content well.", "opportunity_availability": "Open application through Buzzbassador; tier assignment is at TOMS'' discretion.", "ugc_evidence": "A named Creator Tier with published terms, FTC disclosure rules and paid promotion through codes and links shows a structured, active creator program."}'::jsonb);
