  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 10, 14, 8, 9, 5, '{"compensation": "12% per sale is solid for premium footwear, but the 7-day cookie is the shortest in this group; no earnings cap is stated, so the cap is honestly unknown.", "contact_access": "Application runs through the ShareASale listing; no direct program email is published on the fetched pages.", "credibility": "Established premium footwear brand with national retail distribution and a strong quality reputation.", "niche_fit": "Premium sandals and shoes fit travel, beach and everyday-style content, though the niche is narrower than apparel.", "opportunity_availability": "Open network application on ShareASale, available in all regions per the listing.", "ugc_evidence": "An open ShareASale program is the main creator evidence; no published creator campaigns or briefs were found on the fetched pages."}'::jsonb);
