  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Awin', 4, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://ui.awin.com/merchant-profile/6394?setLocale=sv_SE.', 'https://ui.awin.com/merchant-profile/6394?setLocale=sv_SE', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Travelzoo Affiliate Program (Awin) — 4% on local and hotel deals', 'https://ui.awin.com/merchant-profile/6394?setLocale=sv_SE', 'https://ui.awin.com/merchant-profile/6394?setLocale=sv_SE', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/6394?setLocale=sv_SE', 'official_site', 'affiliate', 'Travelzoo''s own Awin merchant profile (US & Canada program, AID 6394) states a standard commission of 4% on the sale amount for local deals and getaways and 4% for hotel deals booked on its platform, with commission approved post-consumption. The profile also states publisher applications generally want a minimum of 500K unique visitors or 50K+ subscribers, with exceptions possible — an eligibility threshold, not a creator count, so creator_saturation is unknown. Two conflicts are documented and not used: an older Awin publisher cheat sheet lists Travelzoo at 8%, and LinkClicky lists a flat $2–$5 per sale. The current merchant profile''s 4% is recorded. No earnings-cap statement appears, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 8, 9, 9, 5, 5, '{"compensation": "4% on local and hotel deals per the current Awin merchant profile; older Awin material says 8% and a listing says $2\u2013$5 flat, both documented as conflicts. No earnings cap is stated, so the cap is honestly unknown.", "contact_access": "Full program terms and application route are published on the Awin merchant profile; no direct email is published.", "credibility": "A long-established, publicly traded travel-deals publisher with a 93% customer review score cited on its Awin profile.", "niche_fit": "Curated travel and local deals are easy to build deal-hunt and getaway content around.", "opportunity_availability": "Application is selective: the profile asks for roughly 500K unique visitors or 50K+ subscribers, with exceptions possible.", "ugc_evidence": "The program is publisher-oriented (data feeds, deal links); no creator-specific briefs or campaigns are published on the profile."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('RedBalloon', 'https://www.redballoon.com.au', 'Australia''s leading online experience retailer, part of Big Red Group (BRG), selling 5,000+ giftable experiences across Australia.', 'Australia', 'published') returning id into bid;
