  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'RedBalloon Partnership Program (Impact) — 3% per sale', 'https://www.redballoon.com.au/affiliate-program.html', 'https://www.redballoon.com.au/affiliate-program.html', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.redballoon.com.au/affiliate-program.html', 'official_site', 'affiliate', 'RedBalloon''s own partnership page states BRG (Big Red Group) affiliates include content creators and publishers, that the program runs on Impact.com for tracking and payouts (paid 50–75 days after the completed action), that affiliates may create their own authentic content, that invite-only briefs offer set compensation and free experiences, and that every $2,000 driven in last-click sales unlocks free experiences to trial. The brand''s own affiliate guidelines PDF sets approval minimums of 3K social followers or 20K monthly Australian web visitors — eligibility minimums, not creator counts, so creator_saturation is unknown. No earnings-cap statement appears, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/redballoon/', 'listing', 'affiliate', 'LinkClicky''s Impact program listing for RedBalloon reports 3% per sale; 3 is recorded. A Shopper.com listing claiming 5–10% is generic boilerplate that conflicts with the network-profile reporting and is documented here but not used.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 15, 7, 10, 8, 4, '{"compensation": "3% per sale (network-profile reporting) is low for the niche, partly offset by free experiences per $2,000 in sales; no earnings cap is stated, so the cap is honestly unknown.", "contact_access": "A dedicated partnership page on the brand''s own domain with the Impact application route and published guidelines.", "credibility": "Australia''s leading experience retailer with 5,000+ experiences, part of Big Red Group.", "niche_fit": "Giftable experiences are made for first-person travel and lifestyle content, and the brand explicitly recruits creators who share experiences.", "opportunity_availability": "Open Impact application with published, reachable minimums (3K social followers or 20K monthly AU visitors).", "ugc_evidence": "The own partnership page and guidelines PDF directly address content creators, encourage original content, and describe invite-only paid briefs and free-experience trials."}'::jsonb);
