  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.ivisa.com/affiliate-terms-and-conditions', 'official_site', 'affiliate', 'iVisa''s own Affiliate Program Terms & Conditions confirm an in-house program: affiliates earn commission on travel-document sales via tracked links (cookie plus IP tracking), are paid on the 15th of each month with a $50 minimum threshold, and must be 18+. The terms deliberately do not publish a percentage (''the commission percentage agreed upon''), and third-party figures conflict — Lasso reports 10–15% per sale, a Daisycon listing reports 8.4%, and Shopper boilerplate says 5–10% — so commission_rate is recorded as null with the conflict documented. The terms state no earnings cap, so commission_cap is unknown, and no absolute creator-count evidence was found, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 21, 8, 8, 9, 8, 4, '{"compensation": "The own terms publish no rate and third-party figures conflict (10\u201315% vs 8.4% vs 5\u201310%), so the rate is honestly recorded as null; payouts are monthly above a $50 threshold. No earnings cap is stated, so the cap is unknown.", "contact_access": "Full program terms are published on the brand''s own domain with the signup route; no direct program email is published.", "credibility": "One of the leading online travel-document processors, operating since 2013.", "niche_fit": "Visa and entry-requirement help is a recurring, practical topic for travel creators planning international trips.", "opportunity_availability": "Open in-house signup, 18+, with approval per the terms.", "ugc_evidence": "The in-house program is publisher-oriented; no creator briefs or campaign terms are published in the terms."}'::jsonb);
