  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'VACAYA Affiliate Program (ShareASale) — flat $100 per lead + $1 per sale', 'https://linkclicky.com/affiliate-program/vacaya/', 'https://linkclicky.com/affiliate-program/vacaya/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/vacaya/', 'listing', 'affiliate', 'LinkClicky''s ShareASale program listing for VACAYA states the program runs on ShareASale and pays a flat $100 per lead plus $1 per sale with a 90-day cookie, open in all regions; because the payout is a flat bounty rather than a percentage, commission_rate is null and the flat structure is documented here. VACAYA''s own ShareASale signup instructions PDF (hosted on the brand''s cdn.myvacaya.com) confirms the ShareASale application route and includes ''VACAYA Influencer'' as an applicant category. No fetched page states an earnings cap, so commission_cap is unknown, and no absolute creator-count evidence was found, so creator_saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 20, 12, 12, 8, 8, 3, '{"compensation": "Flat $100 per lead is a strong bounty for travel content, though the $1 per-sale amount is token; the 90-day cookie is the longest in this group. No earnings cap is stated, so the cap is honestly unknown.", "contact_access": "Application runs through the ShareASale listing and the brand''s own signup instructions; no direct program email is published.", "credibility": "An established specialist charter-vacation operator, smaller and more niche than the mainstream travel brands in this group.", "niche_fit": "A distinctive LGBTQ+ travel niche with strong community content potential, but a narrower audience than mainstream travel.", "opportunity_availability": "Open network application on ShareASale, available in all regions per the listing.", "ugc_evidence": "The brand''s own signup instructions include an explicit ''VACAYA Influencer'' applicant category, showing creators are a deliberate channel."}'::jsonb);
