  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Aer Lingus Affiliate Programme (Impact) — 1–2.5% per booking', 'https://www.aerlingus.com/about-us/partnerships/affiliate-programme/', 'https://www.aerlingus.com/about-us/partnerships/affiliate-programme/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.aerlingus.com/about-us/partnerships/affiliate-programme/', 'official_site', 'affiliate', 'Aer Lingus'' official affiliate programme page states the programme is managed by Omnicom Media Group on Impact Radius, pays 1–2.5% commission for every booking driven, uses a 30-day cookie, pays no commission on Ireland-originating bookings or Avios purchases, and gives aerlingusaffiliates@omnicommediagroup.com as the contact. Because the official page publishes a range rather than a single rate (and third-party listings vary, e.g. 1–2.25%), commission_rate is recorded as null with the range documented. The page''s ''more than 2,000 sales per month'' is sales volume, not a creator count, so creator_saturation is unknown. No earnings-cap statement appears, so commission_cap is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 8, 6, 13, 8, 5, '{"compensation": "1\u20132.5% per booking on the official page is low, as is typical for airlines, and is recorded as a documented range with the rate null. No earnings cap is stated, so the cap is honestly unknown.", "contact_access": "A named programme contact email at the managing agency is published on the official page \u2014 rare for an airline program.", "credibility": "Ireland''s national airline since 1936, part of IAG, with 100+ routes.", "niche_fit": "A flag-carrier airline fits Ireland and transatlantic travel content, though flight booking is a lower-frequency purchase.", "opportunity_availability": "Open application via Impact Radius, reviewed by the Omnicom team for suitability.", "ugc_evidence": "The programme is publisher-focused (no PPC or browser-extension affiliates); no creator briefs are published on the official page."}'::jsonb);
