  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://eatpluck.com/pages/affiliates', 'official_site', 'affiliate', 'Pluck''s official affiliate page states: ''We offer 15% commission on all initial sales and a 60 Day Cookie'', with payouts via ACH, check or gift card on the last Thursday of every month at a $10 minimum. The page states no earnings cap, so commission_cap is recorded as unknown; the tracking platform is not named on the page, so network is null.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://eatpluck.com/pages/affiliates', 'official_site', 'contact', 'The same official page publishes affiliate@eatpluck.com as the program contact, sets eligibility (an established website or business with a 100+ person email list, or a social following over 1,000 followers; coupon/offer sites not accepted), and offers affiliates a 17% personal-purchase coupon code.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 16, 14, 9, 3, '{"compensation": "A verified 15% commission on all initial sales with a 60-day cookie and a low $10 payout threshold, published on the brand''s own page \u2014 top band for this group.", "contact_access": "A dedicated affiliate email (affiliate@eatpluck.com) and a full public program page with requirements \u2014 top band per the rubric.", "credibility": "Small, young DTC brand (Castle Hill Foods) with a niche organ-meat positioning; limited retail footprint and independent coverage so far.", "niche_fit": "A distinctive wellness-food product with a strong ancestral-health and recipe content angle \u2014 a strong food UGC fit.", "opportunity_availability": "The program page is public with clear eligibility (1,000+ followers or a 100+ email list) and an open contact route.", "ugc_evidence": "The program is explicitly built for creators and health advocates with an established audience, and rewards its top affiliate bi-monthly, though no public creator roster is published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Nguyen Coffee Supply', 'https://nguyencoffeesupply.com', 'Vietnamese coffee brand bringing Vietnamese coffee to the specialty scene with ethically sourced whole bean, ground and ready-to-drink coffees roasted fresh in the United States.', 'United States', 'published') returning id into bid;
