  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/nguyen-coffee-supply/', 'affiliate_network', 'compensation', 'Lasso''s directory lists the Nguyen Coffee Supply affiliate program at 7% - 10% per sale with a 30-day cookie in the Coffee and Drink categories.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://admin.shopper.com/partnerships/nguyencoffeesupply-com-affiliate-program', 'listing', 'affiliate', 'Shopper.com''s partnership page for Nguyen Coffee Supply states a payout rate of 2.23 - 3.83% per sale. Because the fetched sources conflict (7-10% vs 2.23-3.83%), commission_rate is recorded as null and the underlying network could not be established from the fetched pages.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 10, 5, 4, 6, 4, '{"compensation": "Directory listings conflict on the rate (7-10% vs 2.23-3.83%), so no rate could be verified and compensation stays at the unverified band.", "contact_access": "No public creator application page or partnerships email was found on the brand''s own pages; routes run through third-party directories only.", "credibility": "Recognized specialty brand credited with bringing Vietnamese coffee to the US specialty scene, with national DTC presence.", "niche_fit": "Vietnamese coffee culture, phin brewing and ready-to-drink products give creators distinctive content angles \u2014 a strong food-drink fit.", "opportunity_availability": "A joinable program exists per network directories, but the brand publishes no program page of its own.", "ugc_evidence": "The brand has a visible creator-friendly specialty coffee profile, but no formal ambassador program or application is published."}'::jsonb);
