  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://brandid.app/blog/best-coffee-affiliate-programs/', 'listing', 'affiliate', 'BrandID''s coffee roundup lists Spirit Animal Coffee at 20% on new customers, up to 27% in VIP tiers, on Awin (formerly ShareASale) with a 60-day cookie — consistent with Lasso''s range.', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sweetandsimplelife.com/coffee-affiliate-programs/', 'listing', 'compensation', 'An older affiliate guide lists Spirit Animal Coffee at 16% commission with a 30-day cookie via the FlexOffers network, and another directory reports typical rates around 10-20% (15% in its FAQ). Because sources conflict on both the base rate (15-20%) and the network (Awin/ShareASale, direct, FlexOffers and Impact all appear), commission_rate and network are recorded as null.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 10, 5, 4, 7, 3, '{"compensation": "Published figures conflict across sources (15%, 16%, and 20-27% all appear), so no rate could be verified despite the program''s high headline numbers.", "contact_access": "No public creator application page or partnerships email was verified on the brand''s own site; joining routes appear only in third-party directories.", "credibility": "Small direct-trade roaster with a compelling sustainability story but limited independent coverage and inconsistent directory data.", "niche_fit": "Premium single-origin coffee with organic and sustainability angles that suit wellness-leaning coffee creators.", "opportunity_availability": "The program is listed as free to join across several directories, though the signup route and network are inconsistently reported.", "ugc_evidence": "Directories describe an accessible, creator-friendly program, but the brand publishes no ambassador community, roster or content program of its own."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('GOOD GOOD', 'https://goodgoodbrand.com', 'Reykjavik-founded brand on a mission to raise the standard for no-added-sugar pantry staples, offering naturally sweetened jams and spreads that are diabetes-friendly, keto-friendly, low-carb and low-calorie.', 'Iceland', 'published') returning id into bid;
