  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'GOOD GOOD Ambassador Application', 'https://docs.google.com/forms/d/e/1FAIpQLSfy4ibtthPXHStsolUMnxQWuZwbeK8lzx_BkEm3MrGgl081ag/viewform', 'https://docs.google.com/forms/d/e/1FAIpQLSfy4ibtthPXHStsolUMnxQWuZwbeK8lzx_BkEm3MrGgl081ag/viewform', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://docs.google.com/forms/d/e/1FAIpQLSfy4ibtthPXHStsolUMnxQWuZwbeK8lzx_BkEm3MrGgl081ag/viewform', 'official_site', 'ugc_collab', 'GOOD GOOD''s official Ambassador Application form confirms the program is open: due to high demand it is only considering ambassadors with public Instagram accounts of at least 2,000 followers, open to those who live in the United States, with selected applicants emailed more information. The form publishes no commission or pay terms, so no affiliate rate is recorded; ''high demand'' is a relative claim, so saturation is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://docs.google.com/forms/d/e/1FAIpQLSfy4ibtthPXHStsolUMnxQWuZwbeK8lzx_BkEm3MrGgl081ag/viewform', 'official_site', 'general', 'The same form describes GOOD GOOD as based in Reykjavik, Iceland, founded in 2015, offering health-conscious jams and spreads that are naturally sweetened, diabetes-friendly, keto-friendly, low-carb, low-calorie and crafted with 100% natural ingredients.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 11, 4, 11, 7, 4, '{"compensation": "The ambassador application publishes no commission, fee or payout terms, so compensation stays at the no-data band.", "contact_access": "A public ambassador application form is openly available, though no direct partnerships email is published.", "credibility": "Founded in 2015 in Reykjavik with international distribution of its no-added-sugar line \u2014 an established brand in its category.", "niche_fit": "No-added-sugar jams and spreads fit health-conscious food, keto and diabetes-friendly creator niches well.", "opportunity_availability": "Applications are open but gated: public Instagram with at least 2,000 followers and US residence required.", "ugc_evidence": "A formal ambassador program with defined eligibility exists on the brand''s own application form, though deliverables and creator community size are not published."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('GORGIE', 'https://getgorgie.com', 'Women-built sparkling energy drink brand with benefits: 150mg green-tea caffeine, zero sugar, L-theanine, biotin and B vitamins in flavors like Tropical Punch, Watermelon Splash and Peach Tea, plus protein energy drinks and drink mixes.', 'United States', 'published') returning id into bid;
