  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://shop.tiktok.com/us/pdp/gorgie-tropical-variety-sugar-free-energy-drink-150mg-caffeine-pack-of-12/1729385034732835382', 'listing', 'affiliate', 'GORGIE''s TikTok Shop product page (shop GETGORGIE, 4.7 rating, 95.8K sold, 74.7K+ followers) displays multiple creator videos tagged ''Creator earns commission'', confirming an active TikTok Shop affiliate program. No commission percentage is published on the page, so commission_rate is null; shop follower counts are not creator counts, so saturation is recorded as unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://creators.spotify.com/pod/profile/100-ways-to-grow-on-tikto/episodes/How-TikTok-Shop-Transformed-Billion-Dollar-Beautys-Growth-Path-e3399nv', 'listing', 'ugc_collab', 'TikTok''s ''100 Ways To Grow On TikTok'' case-study episode describes how GORGIE was built on TikTok, cultivating a wide network of affiliates and running GMV Max campaigns to become the fastest-growing energy drink in the natural channel, with a test product launch sold out driven entirely by affiliate videos.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getgorgie.com', 'official_site', 'general', 'GORGIE''s official homepage describes the brand as ''built by women on a mission to make wellness fun'', selling sparkling energy drinks with 150mg green-tea caffeine, zero sugar, L-theanine, biotin and vitamins B6 and B12; no own-site affiliate or ambassador program is published there.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 5, 4, 8, 4, '{"compensation": "TikTok Shop creators demonstrably earn commission on GORGIE sales, but no commission percentage is published anywhere fetched, so compensation stays at the unverified band.", "contact_access": "No public partnerships email or own-site creator application was found; the only route is TikTok Shop''s creator affiliate flow.", "credibility": "Fast-growing natural-channel energy drink with 95.8K+ units sold through its TikTok shop and a TikTok-published growth case study.", "niche_fit": "A TikTok-native, women-built energy drink with strong visual branding \u2014 near the center of beverage UGC on TikTok.", "opportunity_availability": "Any eligible TikTok Shop creator can promote GORGIE products for commission through the platform''s open affiliate marketplace.", "ugc_evidence": "The brand was built on TikTok with a wide affiliate network, affiliate-driven sellouts and creator videos featured directly on its shop pages."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('TunnelBear', 'https://www.tunnelbear.com', 'Consumer VPN service known for beginner-friendly apps and playful bear branding; owned by McAfee. Its affiliate program pays a flat percentage on every subscription plan sold through a referral link, with no minimum payout.', 'Canada', 'published') returning id into bid;
