  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 50, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://www.tunnelbear.com/affiliate/.', 'https://www.tunnelbear.com/affiliate/', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.tunnelbear.com/affiliate/', 'official_program_page', 'affiliate_program', 'TunnelBear''s own affiliate page (fetched directly) states ''There''s no limit on how much you can earn!'' and ''No minimums — get paid every month, whether it''s $10 or $10,000.'' The page''s join links route to Impact (app.impact.com). No commission percentage is stated on the brand''s own page.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/tunnelbear/', 'affiliate_network', 'commission', 'Lasso''s program profile and VPN roundup list TunnelBear at 50% per sale via Impact (Impact Radius) with a $50 payout threshold; several independent VPN affiliate roundups agree on the 50% rate. Cookie length varies between listings (30 vs 45 days). One directory (Shopper) claims 70% and was treated as unreliable boilerplate.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 15, 20, 8, 9, 5, '["Verified uncapped on the brand''s own affiliate page (''There''s no limit on how much you can earn!'') with a 50% per-sale rate via Impact \u2014 top compensation profile in this group.", "Consumer VPN is a natural fit for tech, privacy and travel creator content, and the brand''s friendly positioning demos well on video.", "No public program email was found on the affiliate page, so contact access is limited to the Impact application."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('PureVPN', 'https://www.purevpn.com', 'Consumer VPN service selling monthly, annual and multi-year plans. Its in-house affiliate program pays 100% commission on monthly-plan signups, 40% on other plans, and 35% recurring lifetime commissions, with a $300 signup bonus.', 'British Virgin Islands', 'published') returning id into bid;
