  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Own program (in-house)', 100, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.purevpn.com/affiliate.', 'https://www.purevpn.com/affiliate', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.purevpn.com/affiliate', 'official_program_page', 'affiliate_program', 'PureVPN''s own affiliate page (fetched directly) states 100% commission on monthly-plan new signups, 40% on other plans, 35% recurring lifetime commissions, a 90-day cookie and a $300 signup bonus, and publishes partners@purevpn.com. Its earnings copy (''sky''s the limit'') is vague marketing with no explicit no-cap statement, so the cap is recorded unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 13, 18, 13, 8, 4, '["Among the highest published VPN rates anywhere: 100% on monthly plans, 40% on other plans, 35% recurring, plus a $300 signup bonus \u2014 all from the brand''s own page.", "A direct program contact (partners@purevpn.com) is published on the affiliate page.", "Cap is honestly unknown: the page''s ''sky''s the limit'' line is marketing language, not an explicit no-cap statement."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Notion', 'https://www.notion.com', 'All-in-one workspace app with a large creator and template-maker community. Its affiliate program explicitly welcomes content creators and influencers, paying up to $50 per activated paid sign-up plus 20% of first-year revenue, tracked through PartnerStack.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'technology'), true);
  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', null, 'https://www.notion.com/affiliates', 'https://www.notion.com/affiliates', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'PartnerStack', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.notion.com/affiliates.', 'https://www.notion.com/affiliates', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.notion.com/affiliates', 'official_program_page', 'affiliate_program', 'Notion''s own affiliates page (fetched directly) states: ''Earn commissions up to $50 per activated sign up plus 20% of year one revenue for each referral you drive'', tracked through PartnerStack, and lists ''Content creators & influencers'' as an eligible audience. Older third-party listings citing 50% of first-year payments describe a previous structure and conflict with the current page, so the mixed flat-plus-revenue-share structure is recorded with a null percentage rate.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.notion.com/affiliates', 'official_program_page', 'application_process', 'The same page explains that conversions are net-new workspaces upgrading to a paid Plus or Business plan within 180 days of the click, links are managed in the PartnerStack dashboard, and promotions must be FTC-disclosed.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 28, 18, 14, 9, 8, 5, '["Explicitly built for creators: the program page lists content creators and influencers as eligible and supports them with a resource center \u2014 exceptional UGC evidence.", "Productivity and template content is a proven short-form niche, giving the program top niche fit for this group.", "Compensation is a hybrid (up to $50 flat per activated sign-up plus 20% of year-one revenue) rather than a high percentage, and older 50% listings conflict with the current page."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('EaseUS', 'https://www.easeus.com', 'Consumer data-recovery, backup and partition software for Windows and Mac. EaseUS runs an affiliate program (30% default, up to 60%) across several networks and a separate creator program paying up to 50%.', 'China', 'published') returning id into bid;
