  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 30, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://pdf.easeus.com/partner/affiliate.html.', 'https://pdf.easeus.com/partner/affiliate.html', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://pdf.easeus.com/partner/affiliate.html', 'official_program_page', 'affiliate_program', 'EaseUS''s official partner page advertises up to 60% commission and publishes affiliate@easeus.com; program listings citing the official page put the default rate at 30%. The program is carried on multiple networks (Impact, CJ, Partnerize), and a FlexOffers listing shows 40%, so the recorded rate is the 30% default.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.easeus.com/partner/creator-program.html', 'official_program_page', 'creator_program', 'EaseUS also runs a dedicated creator program on its own domain paying up to 50%, separate from the standard affiliate program.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 14, 15, 13, 9, 4, '["A dedicated creator program (up to 50%) on top of the standard affiliate program is strong creator evidence for a software brand.", "Published program contact (affiliate@easeus.com) and multiple network doors make access straightforward.", "Headline ''up to 60%'' is a ceiling, not the default; the recorded 30% default keeps compensation scoring honest."]'::jsonb);
