  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.wondershare.com/business/affiliate.html', 'official_program_page', 'affiliate_program', 'Wondershare''s own affiliate pages describe tiered commissions starting at 30% for lower quarterly sales and rising to 50% at the highest tier, and publish affiliate@wondershare.com for the program. Listings place the program on CJ, Impact, ShareASale, Awin and LinkConnector; CJ is recorded as the primary network.', 'publicly_reported', now());
