  insert into public.brands (name, website, description, country, status) values ('NordPass', 'https://nordpass.com', 'Password manager from the Nord Security team behind NordVPN. Its in-house affiliate program pays 30% on new B2C sign-ups and 10% on renewals, with a $100 minimum payout.', 'Lithuania', 'published') returning id into bid;
