  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://nordpass.com/affiliate/', 'official_program_page', 'affiliate_program', 'NordPass''s own affiliate pages state B2C commissions of 30% on new sign-ups and 10% on renewals (B2B new sign-ups 25%), run as an in-house program with a $100 payout minimum. A Lasso roundup claiming 75% conflicts with the brand''s own published structure and was not used.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 12, 15, 8, 8, 5, '["Backed by the Nord Security brand, giving it top credibility in this group.", "30% on new sign-ups plus 10% recurring on renewals is a fair, clearly published structure from the brand''s own pages.", "No public program email was recorded and the $100 payout minimum slows first earnings for small creators."]'::jsonb);
