  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 10, 14, 11, 7, 4, '["Clean 30% revenue share stated on the brand''s own affiliates page, with a published program contact.", "Password managers are a crowded creator niche (NordPass is in this same group), trimming niche fit.", "No renewal commissions and a network-attribution conflict between listings keep the score mid-pack."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Embrace Pet Insurance', 'https://www.embracepetinsurance.com', 'US pet insurance provider for dogs and cats. Its affiliate program pays a flat $36 bounty per qualified lead with a long 180-day cookie, a fit for pet creators making insurance and pet-cost content.', 'United States', 'published') returning id into bid;
