  insert into public.brands (name, website, description, country, status) values ('Instant Brands', 'https://instanthome.com', 'Maker of Instant Pot multi-cookers and other Instant kitchen appliances, now trading as Instant Pot Brands after a 2023 Chapter 11 restructuring. An affiliate program exists, but published rates and management conflict across sources, so terms must be confirmed at application.', 'United States', 'published') returning id into bid;
