  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'CJ Affiliate', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://getlasso.co/affiliate/instant-brands/.', 'https://getlasso.co/affiliate/instant-brands/', 'needs_review', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/instant-brands/', 'third_party_listing', 'affiliate_program', 'Published Instant Brands affiliate terms conflict sharply: Lasso''s current profile lists 4% per sale (45-day cookie), LinkClicky lists 1% per sale on CJ Affiliate (March 2024), AdCompares lists a flat 3% managed directly by Gen3 Marketing, and an older Refersion profile cited 8%. Because the rate and even the managing network conflict, the commission rate is recorded null. Sovrn''s merchant page also notes that, following the 2023 restructuring, current affiliate availability has not been independently verified — confirm live terms before promoting.', 'needs_review', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 10, 6, 6, 6, 4, '["Instant Pot demos exceptionally well in recipe and kitchen content, keeping niche fit respectable despite the weak terms.", "Rate is recorded null: published figures conflict across four sources (1%, 3%, 4%, 8%).", "Post-bankruptcy restructuring and unverified current merchant status (per Sovrn) cap credibility and availability scores until terms are confirmed live."]'::jsonb);
